<script>
// --- Simulated page-detail lookup (prototype only) ---
// Stands in for automatically reading a page's title/site/description.
const KNOWN = {
  "nasa.gov/webb": {
    title: "NASA's James Webb Space Telescope",
    site: "nasa.gov",
    desc: "The largest, most powerful space telescope ever built, revealing the universe in infrared light — from the earliest galaxies to exoplanet atmospheres.",
    emoji: "🔭"
  },
  "developer.mozilla.org/css-grid": {
    title: "CSS Grid Layout — MDN Web Docs",
    site: "developer.mozilla.org",
    desc: "A complete guide to CSS Grid: rows, columns, areas, and alignment, with examples and browser support notes.",
    emoji: "📘"
  },
  "recipes.example.com/ramen": {
    title: "Rich Tonkotsu Ramen from Scratch",
    site: "recipes.example.com",
    desc: "A weekend project: 12-hour pork bone broth, homemade tare, and springy noodles. Step-by-step with photos.",
    emoji: "🍜"
  }
};

function lookup(url) {
  let clean = url.replace(/^https?:\/\//i, "").replace(/^www\./i, "").replace(/\/+$/,"");
  for (const key in KNOWN) {
    if (clean.toLowerCase().startsWith(key.toLowerCase())) {
      return { ...KNOWN[key], url };
    }
  }
  // Fallback: derive a readable title/site from the URL itself.
  let host = clean.split("/")[0];
  let path = clean.split("/").slice(1).join("/");
  let guessTitle = path
    ? decodeURIComponent(path.split(/[/?#]/)[0]).replace(/[-_]+/g," ").replace(/\.\w+$/,"").trim()
    : host;
  guessTitle = guessTitle ? guessTitle.replace(/\b\w/g, c => c.toUpperCase()) : host;
  return {
    title: guessTitle || host,
    site: host,
    desc: "",
    emoji: "🔖",
    url
  };
}

const listEl = document.getElementById("list");
const emptyEl = document.getElementById("empty");
const input = document.getElementById("url");
const btn = document.getElementById("saveBtn");

function refreshEmpty() {
  emptyEl.style.display = listEl.children.length ? "none" : "block";
}

function timeLabel() {
  const d = new Date();
  return "Saved just now · " + d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

function save() {
  const url = input.value.trim();
  if (!url) { input.focus(); return; }

  btn.disabled = true;
  // Insert a loading card first (simulates fetching details).
  const card = document.createElement("div");
  card.className = "card loading";
  card.innerHTML = `
    <div class="thumb">⏳</div>
    <div class="card-body">
      <div class="skeleton w70"></div>
      <div class="skeleton w40"></div>
      <div class="skeleton w90"></div>
    </div>`;
  listEl.prepend(card);
  refreshEmpty();

  setTimeout(() => {
    const m = lookup(url);
    card.className = "card";
    card.innerHTML = `
      <div class="thumb">${m.emoji || "🔖"}</div>
      <div class="card-body">
        <div class="card-title">${escapeHtml(m.title)}</div>
        <div class="card-site"><span>🌐</span>${escapeHtml(m.site)}</div>
        ${m.desc ? `<p class="card-desc">${escapeHtml(m.desc)}</p>` : ""}
        <div class="card-url">${escapeHtml(m.url)}</div>
        <div class="card-meta">${timeLabel()}</div>
      </div>`;
    input.value = "";
    btn.disabled = false;
    input.focus();
  }, 850);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
}

btn.addEventListener("click", save);
input.addEventListener("keydown", e => { if (e.key === "Enter") save(); });

refreshEmpty();
document.body.setAttribute("data-harness-ready", "true");
</script>
